INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('inversions', 8, NULL, 'def gen():
    _s = [410196072]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    V = 1000000000
    MODE = 0
    N = 200000
    if MODE == 1:
        a = list(range(N, 0, -1))
    else:
        a = [r(1, V) for _ in range(N)]
    return f"{N}\n{'' ''.join(map(str, a))}\n"
', '10033594939', 0);
